/**
 * Project Brain K7a (design §6.3 L1): which files the 지도 counts and how it reads them, per language.
 * Not made by hand: the extension → language table and each language's comment syntax come from two MIT
 * open-source data files (languageTable.generated.ts: GitHub Linguist and tokei, regenerated by
 * scripts/generate-languages.mjs). Made by hand, because neither has them: the test-file name rule and
 * the shape of a test's name (where a display ID in a test name is read) of the languages below. Only TS
 * and JS also have their import lines read (mapWorker.ts); every other language's files are cells and
 * numbers, without arrows (L2, tree-sitter, is K7b).
 */
import { CODE_LANGUAGES, DATA_EXT, PROSE_EXT } from './languageTable.generated.js';

export interface Language {
  /** Shown in the footer. */
  name: string;
  /** The comment starts a head-comment tag may follow (regex source). */
  comment: string;
  /** A test file's name (the path). */
  test: RegExp;
  /** A test's name (the whole declaration, a display ID inside it counts): `global`, `multiline`. */
  testName?: RegExp;
  /** Test files sit beside the code in this language's layer (TS and JS: the existing map); the others go to the tests rail. */
  beside?: true;
  /** The relative import lines of this language are read. */
  imports?: true;
}

/** What is hand-made, because Linguist and tokei do not have it: per language, its test files' names and its tests' names. */
interface Rule extends Omit<Language, 'comment'> {
  ext: string;
  /** Comment starts the table lacks (Python's docstrings). */
  comment?: string;
}

/** A test's name in TS and JS: the first argument of `it(`, `test(`, `describe(` (and their `.only`/`.skip`), a plain string. */
const JS_TEST_NAME = /\b(?:it|test|describe)(?:\.(?:only|skip|todo|concurrent))?\(\s*(['"`])((?:\\.|(?!\1)[^\\\n])*)\1/g;
const NONE = /(?!)/g;

// ponytail: a test-name regex per language reads declaration lines and string arguments only (no parse); a name built at run time or a table-driven case is not seen. tree-sitter (K7b) is the upgrade.
const RULES: readonly Rule[] = [
  { name: 'TypeScript', ext: 'ts tsx mts cts', test: /\.(test|spec)\.[cm]?tsx?$/, testName: JS_TEST_NAME, beside: true, imports: true },
  { name: 'JavaScript', ext: 'js jsx mjs cjs', test: /\.(test|spec)\.[cm]?jsx?$/, testName: JS_TEST_NAME, beside: true, imports: true },
  { name: 'Python', ext: 'py pyi pyw', comment: '"""|\'\'\'', test: /(^|\/)(test_[^/]*|[^/]*_test|conftest)\.pyi?$/, testName: /^[ \t]*(?:@pytest\.[^\n]*|(?:async\s+)?def\s+test\w*[^\n]*|class\s+Test\w*[^\n]*)$/gm },
  { name: 'Go', ext: 'go', test: /_test\.go$/, testName: /^func\s+(?:Test|Benchmark|Example)\w*[^\n]*$|\bt\.Run\(\s*"[^"\n]*"/gm },
  { name: 'Rust', ext: 'rs', test: /(^|\/)(tests\/[^/]*|[^/]*_tests?)\.rs$/, testName: /#\[(?:\w+::)?test[^\]]*\][^\n]*\n(?:[ \t]*#\[[^\]\n]*\][^\n]*\n)*[ \t]*(?:async\s+)?fn\s+\w+/g },
  { name: 'Java', ext: 'java', test: /(^|\/)(Test[^/]*|[^/]*(Tests?|IT|Spec))\.java$/, testName: /@DisplayName\(\s*"[^"\n]*"\s*\)|@(?:Test|ParameterizedTest)[^\n]*(?:\n[ \t]*@[^\n]*)*\n[ \t]*(?:public\s+|private\s+|protected\s+)?(?:static\s+)?\w+\s+\w+/g },
  { name: 'Kotlin', ext: 'kt kts', test: /(^|\/)[^/]*(Tests?|IT|Spec)\.kt$/, testName: /@(?:Test|ParameterizedTest|DisplayName)[^\n]*(?:\n[ \t]*@[^\n]*)*\n[ \t]*fun\s+[^(\n]+|\b(?:it|test|describe|context)\(\s*"[^"\n]*"/g },
  { name: 'C', ext: 'c h', test: /(^|\/)(test_[^/]*|[^/]*_tests?)\.c$/ },
  { name: 'C++', ext: 'cc cpp cxx hpp hh hxx', test: /(^|\/)(test_[^/]*|[^/]*_(?:unit)?tests?)\.(cc|cpp|cxx)$/, testName: /\b(?:TEST|TEST_F|TEST_P|TYPED_TEST|TEST_CASE|SCENARIO|SECTION)\s*\([^\n]*/g },
  { name: 'C#', ext: 'cs', test: /(^|\/)[^/]*(Tests?|Spec)\.cs$/, testName: /\[(?:Fact|Theory|Test|TestCase|TestMethod)[^\]\n]*\][^\n]*(?:\n[ \t]*\[[^\]\n]*\][^\n]*)*\n[ \t]*(?:public\s+)?(?:async\s+)?[\w<>]+\s+\w+/g },
  { name: 'Ruby', ext: 'rb rake', test: /(^|\/)([^/]*_(?:test|spec)|test_[^/]*)\.rb$/, testName: /^[ \t]*(?:it|describe|context|test|specify|scenario|feature)\b[ \t(]*(['"])(?:\\.|(?!\1)[^\\\n])*\1|^[ \t]*def\s+test_\w+/gm },
  { name: 'PHP', ext: 'php', test: /(^|\/)[^/]*Test\.php$/, testName: /function\s+test\w+[^\n]*|\b(?:it|test|describe)\(\s*(['"])(?:\\.|(?!\1)[^\\\n])*\1/g },
  { name: 'Swift', ext: 'swift', test: /(^|\/)[^/]*Tests?\.swift$/, testName: /func\s+test\w+[^\n]*|@Test\b[^\n]*/g },
  { name: 'Shell', ext: 'sh bash zsh bats', comment: '#', test: /(^|\/)([^/]*[-_.]test|test[-_.][^/]*)\.(sh|bash|zsh)$|\.bats$/, testName: /^@test\s+(["'])(?:\\.|(?!\1)[^\\\n])*\1|^[ \t]*(?:function\s+)?test_\w+[ \t]*\(\)/gm },
  { name: 'SQL', ext: 'sql', test: /(^|\/)[^/]*_test\.sql$/ },
  { name: 'Scala', ext: 'scala sc', test: /(^|\/)[^/]*(Test|Spec|Suite)\.scala$/, testName: /\b(?:test|it|describe)\(\s*"[^"\n]*"|"[^"\n]*"\s+(?:should|in|must)\b[^\n]*/g },
  { name: 'Dart', ext: 'dart', test: /_test\.dart$/, testName: /\b(?:test|testWidgets|group)\(\s*(['"])(?:\\.|(?!\1)[^\\\n])*\1/g },
  { name: 'Lua', ext: 'lua', test: /_spec\.lua$/, testName: /\b(?:it|describe)\(\s*(['"])(?:\\.|(?!\1)[^\\\n])*\1/g },
  { name: 'Perl', ext: 'pl pm', test: /\.t$/, testName: /\b(?:ok|is|like|subtest)\b[^\n]*/g },
  { name: 'Elixir', ext: 'ex exs', test: /_test\.exs$/, testName: /^[ \t]*(?:test|describe)\s+"[^"\n]*"/gm },
];
const RULE_BY_EXT = new Map(RULES.flatMap((r) => r.ext.split(' ').map((e) => [e, r] as const)));

/** The table's rows by extension: name and comment starts (Linguist and tokei, generated). */
const TABLE = new Map(CODE_LANGUAGES.flatMap(([name, exts, comment]) => exts.split(' ').map((e) => [e, { name, comment }] as const)));
const EXT_SET = (list: string) => new Set(list.split(' '));
/** Settings and data, documents: counted apart, never opened (Linguist's data and prose extensions). */
const CONFIG_EXT = EXT_SET(DATA_EXT);
const DOC_EXT = EXT_SET(PROSE_EXT);

const extOf = (file: string) => {
  const i = file.lastIndexOf('.');
  return i > file.lastIndexOf('/') ? file.slice(i + 1).toLowerCase() : '';
};

const BY_EXT = new Map<string, Language | null>();
/** A file's language (every language of the table; those with a rule also know their tests), or undefined (a setting, a document, anything else). */
export const languageOf = (file: string): Language | undefined => {
  const e = extOf(file);
  let l = BY_EXT.get(e);
  if (l === undefined) {
    const r = RULE_BY_EXT.get(e);
    const row = TABLE.get(e);
    const comment = [...new Set([row?.comment, r?.comment].filter(Boolean))].join('|');
    l = row || r ? { name: r?.name ?? row!.name, comment, test: r?.test ?? NONE, ...(r?.testName && { testName: r.testName }), ...(r?.beside && { beside: true as const }), ...(r?.imports && { imports: true as const }) } : null;
    BY_EXT.set(e, l);
  }
  return l ?? undefined;
};
export const JS_LANG = languageOf('x.js')!;

/** What a file that is no code is counted as. */
export const otherKind = (file: string): 'config' | 'docs' | null => {
  const e = extOf(file);
  return languageOf(file) ? null : CONFIG_EXT.has(e) ? 'config' : DOC_EXT.has(e) ? 'docs' : null;
};

/** Folders no project's own code lives in: dependencies, builds, caches (python, rust, java, swift, ruby, go, js). */
export const SKIP_DIRS =
  /(^|\/)(node_modules|dist|public|\.venv|venv|__pycache__|site-packages|\.tox|\.mypy_cache|\.pytest_cache|target|build|\.gradle|Pods|vendor)\//;

/** A test file by its name in a language whose tests do not sit beside the code (the tests rail). */
export const isTestFileOutsideJs = (file: string): boolean => {
  const l = languageOf(file);
  return !!l && !l.beside && l.test.test(file);
};
/** A test file by its name, any language (a file whose numbers count only in its test names). */
export const isTestFile = (file: string): boolean => !!languageOf(file)?.test.test(file);

/** The regex for a language's head-comment tag lines (a capital dashed word after a comment start). */
const TAG_RES = new Map<string, RegExp>();
export const tagLine = (l: Language): RegExp => {
  let re = TAG_RES.get(l.comment);
  if (!re) TAG_RES.set(l.comment, (re = l.comment ? new RegExp(String.raw`^\s*(?:${l.comment})\**\s*([A-Z][A-Z0-9]{1,11}(?:-[A-Z0-9]{1,11})+)\b`, 'gm') : NONE));
  re.lastIndex = 0;
  return re;
};
export const testNameLine = (l: Language): RegExp => {
  const re = l.testName ?? NONE;
  re.lastIndex = 0;
  return re;
};
